    def override_screening_answer(
        self,
        question_text: str,
        options: Optional[List[str]] = None,
        candidate_data: Optional[Dict[str, Any]] = None
    ) -> Optional[str]:
        """
        JPMC curated screening questionnaire matching.
        """
        if not question_text:
            return None

        q = question_text.lower().strip()
        data = candidate_data or {}
        cand = data.get("candidate", data)

        # 1. Age Gate (18+)
        if "at least 18 years of age" in q or "18 years" in q:
            return self._match_choice("Yes", options)

        # 2. Legal Work Authorization
        if "legally authorized to work" in q or "authorized to work in this country" in q:
            # Domestic citizen applying in home country
            cand_country = str(cand.get("country", "")).lower()
            citizenship = str(cand.get("citizenship", "")).lower()
            if "india" in citizenship or "india" in cand_country:
                return self._match_choice("Yes", options)
            return self._match_choice("Yes", options)

        # 3. Visa Sponsorship
        if "sponsorship for an employment-based visa" in q or "require sponsorship" in q:
            return self._match_choice("No", options)

        # 4. Indian Passport
        if "hold an indian passport" in q:
            return self._match_choice("Yes", options)

        # 5. Dual / Foreign Citizenship
        if "citizenship or a passport of any country other than" in q:
            return self._match_choice("No", options)

        # 6. High School Diploma / 10+2
        if "high school diploma" in q or "10+2" in q:
            return self._match_choice("Yes", options)

        # 7. Relevant Years of Work Experience Tier
        if "relevant years of work experience" in q or "years of work experience you have" in q:
            total_exp = float(cand.get("total_experience_years", 0))
            if options:
                # Parse numeric tiers from options
                best_option = None
                highest_threshold = -1.0
                for opt in options:
                    nums = [float(n) for n in re.findall(r'\d+', opt)]
                    threshold = max(nums) if nums else 0.0
                    if "no prior" in opt.lower() or "none" in opt.lower():
                        threshold = 0.0
                    if total_exp >= threshold and threshold > highest_threshold:
                        highest_threshold = threshold
                        best_option = opt
                if best_option:
                    return best_option

        # 8. Primary Area of Expertise
        if "primary area of expertise" in q and options:
            for opt in options:
                if "software engineering" in opt.lower():
                    return opt

        # 9. AWS Proficiency
        if "proficiency with aws" in q or "proficiency level in aws" in q:
            return self._match_choice("Advanced / Expert", options) or self._match_choice("Advanced", options)

        # 10. Area of Focus within Software Engineering
        if "area of focus" in q and options:
            for opt in options:
                if "fullstack" in opt.lower() or "java fullstack" in opt.lower():
                    return opt

        return None

    def _match_choice(self, target: str, options: Optional[List[str]]) -> Optional[str]:
        if not options:
            return target
        target_l = target.lower().strip()
        for opt in options:
            if opt.lower().strip() == target_l:
                return opt
        for opt in options:
            if target_l in opt.lower():
                return opt
        return options[0] if options else target

class ReviewVerifier:
    """
    Coordinates post-upload verification and healing of ATS form fields.
    """

    @classmethod
    def audit_and_heal_experience_descriptions(cls, page: Any) -> List[Dict[str, Any]]:
        """
        Scans all visible textareas on page (typically role descriptions), checks for
        broken margin line wraps, heals them, and updates the DOM.
        """
        healed_reports = []
        try:
            textareas = page.locator("textarea:visible").all()
            for idx, ta in enumerate(textareas):
                raw_text = ta.input_value()
                if not raw_text or len(raw_text.strip()) < 20:
                    continue

                healed_text = LineWrapHealer.heal_text(raw_text)
                if healed_text != raw_text:
                    # Update DOM
                    ta_id = ta.get_attribute("id")
                    if ta_id:
                        selector = f"textarea#{ta_id}"
                    else:
                        selector = f"textarea:nth-of-type({idx + 1})"

                    success = DOMHelpers.set_input_value_native(page, selector, healed_text)
                    healed_reports.append({
                        "field_index": idx,
                        "selector": selector,
                        "original_length": len(raw_text),
                        "healed_length": len(healed_text),
                        "success": success
                    })
        except Exception as e:
            healed_reports.append({"error": str(e)})

        return healed_reports

    @classmethod
    def audit_and_heal_education_fields(cls, page: Any, ground_truth_education: Optional[List[Dict[str, Any]]] = None) -> List[Dict[str, Any]]:
        """
        Scans education section fields on page, validates against ground truth,
        and corrects inverted school/degree inputs.
        """
        reports = []
        # Target common education input identifiers across Workday, Oracle, and Greenhouse
        school_selectors = [
            "input[id*='school']", "input[name*='school']",
            "input[id*='institution']", "input[name*='institution']",
            "input[data-automation-id*='school']"
        ]
        degree_selectors = [
            "input[id*='degree']", "input[name*='degree']",
            "input[data-automation-id*='degree']"
        ]

        try:
            school_el = None
            school_sel = ""
            for s in school_selectors:
                if page.locator(s).count() > 0 and page.locator(s).first.is_visible():
                    school_el = page.locator(s).first
                    school_sel = s
                    break

            degree_el = None
            degree_sel = ""
            for d in degree_selectors:
                if page.locator(d).count() > 0 and page.locator(d).first.is_visible():
                    degree_el = page.locator(d).first
                    degree_sel = d
                    break

            if school_el and degree_el:
                parsed_school = school_el.input_value()
                parsed_degree = degree_el.input_value()

                diagnosis = EducationHealer.diagnose_and_heal_entry(
                    parsed_school, parsed_degree, ground_truth_education=ground_truth_education
                )

                if diagnosis.get("was_modified"):
                    DOMHelpers.set_input_value_native(page, school_sel, diagnosis["school"])
                    DOMHelpers.set_input_value_native(page, degree_sel, diagnosis["degree"])
                    reports.append({
                        "school_selector": school_sel,
                        "degree_selector": degree_sel,
                        "diagnosis": diagnosis
                    })
        except Exception as e:
            reports.append({"error": str(e)})

        return reports

class DOMHelpers:
    """
    Robust DOM helper methods for modern Single-Page ATS Applications (Oracle JET, React, Angular).
    """

    @staticmethod
    def set_input_value_native(page: Any, selector: str, value: str, timeout_ms: int = 5000) -> bool:
        """
        Safely sets value into an input or textarea using native property setter and dispatches
        synthetic events so React / Oracle JET internal models update correctly.
        """
        try:
            page.wait_for_selector(selector, timeout=timeout_ms, state="visible")
            locator = page.locator(selector)
            locator.scroll_into_view_if_needed()
            locator.click()

            # Execute native property setter and event dispatch in page context
            page.evaluate("""({sel, val}) => {
                const el = document.querySelector(sel);
                if (!el) return false;

                // Focus element
                el.focus();

                // Use native HTMLInputElement / HTMLTextAreaElement value setter to bypass framework wrappers
                const proto = el.tagName === 'TEXTAREA' ? window.HTMLTextAreaElement.prototype : window.HTMLInputElement.prototype;
                const nativeSetter = Object.getOwnPropertyDescriptor(proto, 'value')?.set;
                if (nativeSetter) {
                    nativeSetter.call(el, val);
                } else {
                    el.value = val;
                }

                // Dispatch full synthetic event chain
                el.dispatchEvent(new Event('input', { bubbles: true, cancelable: true }));
                el.dispatchEvent(new Event('change', { bubbles: true, cancelable: true }));
                el.dispatchEvent(new Event('blur', { bubbles: true, cancelable: true }));
                return true;
            }""", {"sel": selector, "val": value})
            return True
        except Exception as e:
            # Fallback to standard Playwright fill
            try:
                page.locator(selector).fill(value, timeout=2000)
                return True
            except Exception:
                return False

    @staticmethod
    def set_checkbox_checked(page: Any, selector: str, checked: bool = True, timeout_ms: int = 5000) -> bool:
        """
        Checks or unchecks a checkbox safely. If the native checkbox is hidden behind a custom
        label/styled span (common in Oracle JET and Workday), clicks the parent or associated label.
        """
        try:
            locator = page.locator(selector)
            is_checked = locator.is_checked()
            if is_checked == checked:
                return True

            # Attempt standard check
            try:
                if checked:
                    locator.check(force=True, timeout=2000)
                else:
                    locator.uncheck(force=True, timeout=2000)
                return True
            except Exception:
                pass

            # Fallback: JavaScript direct click & event dispatch
            page.evaluate("""({sel, shouldCheck}) => {
                const el = document.querySelector(sel);
                if (!el) return false;

                // If wrapped by label, click label
                const label = el.closest('label') || document.querySelector(`label[for="${el.id}"]`);
                if (label) {
                    label.click();
                    return true;
                }

                el.checked = shouldCheck;
                el.dispatchEvent(new Event('change', { bubbles: true }));
                el.dispatchEvent(new Event('click', { bubbles: true }));
                return true;
            }""", {"sel": selector, "shouldCheck": checked})
            return True
        except Exception:
            return False

    @staticmethod
    def extract_form_schema(page: Any) -> Dict[str, Any]:
        """
        Inspects the active page DOM and returns a comprehensive structured catalog
        of all inputs, textareas, selects, radio groups, checkboxes, honeypots, and buttons.
        """
        script = """() => {
            const results = {
                title: document.title,
                url: window.location.href,
                headings: [],
                inputs: [],
                buttons: []
            };

            // Headings
            document.querySelectorAll('h1, h2, h3, [role="heading"]').forEach(h => {
                const txt = h.innerText?.trim();
                if (txt) results.headings.push(txt);
            });

            // Form controls
            const controls = document.querySelectorAll('input, textarea, select');
            controls.forEach((el, idx) => {
                const style = window.getComputedStyle(el);
                const rect = el.getBoundingClientRect();
                const isVisible = style.display !== 'none' && 
                                  style.visibility !== 'hidden' && 
                                  style.opacity !== '0' && 
                                  rect.width > 0 && rect.height > 0;

                // Find associated label text
                let labelText = '';
                if (el.id) {
                    const l = document.querySelector(`label[for="${el.id}"]`);
                    if (l) labelText = l.innerText?.trim();
                }
                if (!labelText) {
                    const parentLabel = el.closest('label');
                    if (parentLabel) labelText = parentLabel.innerText?.trim();
                }
                if (!labelText) {
                    labelText = el.getAttribute('aria-label') || el.placeholder || '';
                }

                results.inputs.push({
                    index: idx,
                    tagName: el.tagName.toLowerCase(),
                    type: el.getAttribute('type') || (el.tagName.toLowerCase() === 'textarea' ? 'textarea' : 'text'),
                    name: el.getAttribute('name') || '',
                    id: el.getAttribute('id') || '',
                    className: el.className || '',
                    placeholder: el.placeholder || '',
                    ariaLabel: el.getAttribute('aria-label') || '',
                    labelText: labelText,
                    value: el.value || '',
                    checked: el.checked || false,
                    required: el.required || el.getAttribute('aria-required') === 'true',
                    disabled: el.disabled || el.getAttribute('aria-disabled') === 'true',
                    readOnly: el.readOnly || false,
                    isVisible: isVisible,
                    styleSnippet: `display:${style.display}; visibility:${style.visibility}; opacity:${style.opacity}`
                });
            });

            // Buttons
            document.querySelectorAll('button, input[type="submit"], input[type="button"], a.button, [role="button"]').forEach((b, idx) => {
                const style = window.getComputedStyle(b);
                const rect = b.getBoundingClientRect();
                const isVisible = style.display !== 'none' && 
                                  style.visibility !== 'hidden' && 
                                  rect.width > 0 && rect.height > 0;
                results.buttons.push({
                    index: idx,
                    text: b.innerText?.trim() || b.getAttribute('aria-label') || b.value || '',
                    type: b.getAttribute('type') || '',
                    className: b.className || '',
                    disabled: b.disabled || b.getAttribute('aria-disabled') === 'true',
                    isVisible: isVisible
                });
            });

            return results;
        }"""
        try:
            return page.evaluate(script)
        except Exception as e:
            return {"error": str(e), "url": getattr(page, "url", "")}

def extract_years_from_tenure(text: str) -> tuple:
    """
    Extracts start and end years from any tenure/duration string.
    Rule C16: Required for multi-attribute duplicate detection.
    """
    clean = str(text or "").strip().lower()
    four_digit = re.findall(r'\b(19\d\d|20\d\d)\b', clean)
    if four_digit:
        start_yr = int(four_digit[0])
        end_yr = int(four_digit[-1]) if len(four_digit) > 1 else ('present' if 'present' in clean else start_yr)
        return (start_yr, end_yr)
    two_digit = re.findall(r"(?:'|’|\b)(\d{2})\b", clean)
    if two_digit:
        start_yr = 2000 + int(two_digit[0])
        end_yr = 2000 + int(two_digit[-1]) if len(two_digit) > 1 else ('present' if 'present' in clean else start_yr)
        return (start_yr, end_yr)
    return (None, None)

def inspect_live_naukri_profile(page) -> Dict[str, Any]:
    """
    Step B: Non-destructive live inspection of candidate's Naukri profile.
    Extracts current headline, summary, key skills, and employment records from the live DOM.
    """
    log("\n[STEP B] Inspecting Live Naukri Profile DOM...")
    page.goto("https://www.naukri.com/mnjuser/profile", wait_until="domcontentloaded", timeout=35000)
    page.wait_for_timeout(3000)

    # Pre-inspection scroll: Naukri defers mounting #lazyEmployment and #lazyKeySkills until scrolled into viewport
    try:
        page.evaluate("""() => {
            window.scrollTo(0, 500);
            setTimeout(() => window.scrollTo(0, 1200), 250);
        }""")
        page.wait_for_timeout(1500)
    except Exception:
        pass

    live_headline = ""
    headline_el = page.locator(".resumeHeadline .widgetHead, .widgetHead:has-text('Resume Headline')").first
    if headline_el.count() > 0:
        headline_text_el = page.locator(".resumeHeadline .typ-14Medium, .resumeHeadline .text, .resumeHeadline p").first
        if headline_text_el.count() > 0:
            live_headline = headline_text_el.inner_text().strip()

    live_summary = ""
    summary_el = page.locator(".card:has(.widgetTitle:text('Profile summary')), span:has-text('Profile summary'), .profileSummary").first
    if summary_el.count() > 0:
        summary_text_el = page.locator(".profileSummary .text, .profileSummary p, .profileSummary .typ-14Medium").first
        if summary_text_el.count() > 0:
            live_summary = summary_text_el.inner_text().strip()

    live_skills = []
    skill_chips = page.locator(".keySkills .chip, .keySkills span.chip, #lazyKeySkills .chip, div[class*='keySkills'] a").all()
    for sc in skill_chips:
        txt = sc.inner_text().strip()
        if txt and txt not in live_skills:
            live_skills.append(txt)

    live_employments = []
    emp_cards = page.locator("#lazyEmployment .emp-list, .emp-list, div[class*='employment-list']").all()
    log(f"    Discovered {len(emp_cards)} existing employment card(s) on Naukri.")

    for i, card in enumerate(emp_cards):
        try:
            card_text = card.inner_text()
            lines = [l.strip() for l in card_text.split("\n") if l.strip()]

            designation = ""
            company = ""
            tenure = ""
            live_desc = ""

            if len(lines) >= 1:
                designation = lines[0]
            if len(lines) >= 2:
                company = lines[1]
            if len(lines) >= 3:
                tenure = lines[2]

            desc_el = card.locator(".job-desc, .desc, p[class*='desc'], .jobDescription").first
            if desc_el.count() > 0 and desc_el.is_visible():
                live_desc = desc_el.inner_text().strip()

            if not live_desc:
                try:
                    edit_btn = card.locator("span.edit, .editOneTheme").first
                    if edit_btn.count() > 0 and edit_btn.is_visible():
                        edit_btn.click()
                        page.wait_for_timeout(1500)

                        desc_box = page.locator("#jobDescription, textarea#jobDescription").first
                        if desc_box.count() > 0 and desc_box.is_visible():
                            live_desc = desc_box.input_value() or desc_box.inner_text() or ""

                        cancel_btn = page.locator("form#employmentForm a.cancel-btn, form#employmentForm button:has-text('Cancel'), .crossIcon").first
                        if cancel_btn.count() > 0 and cancel_btn.is_visible():
                            cancel_btn.click()
                        else:
                            page.keyboard.press("Escape")
                        page.wait_for_timeout(1000)
                except Exception as ex:
                    log(f"      [Notice] Could not inspect modal for card {i}: {ex}")

            live_employments.append({
                "index": i,
                "company": company.strip(),
                "designation": designation.strip(),
                "tenure": tenure.strip(),
                "description": live_desc.strip(),
                "raw_text": card_text
            })
            log(f"      - Live Card #{i+1}: '{designation}' at '{company}' (Desc length: {len(live_desc)} chars)")
        except Exception as e:
            log(f"      [!] Error reading employment card {i}: {e}")

    # Step B.2: Also inspect Naukri Campus Internship cards if present (Rule C16)
    campus_intern_cards = page.locator(".internship-details .card-container, .internshipDetails .card-container, div[id*='internshipDetails-']").all()
    if campus_intern_cards:
        log(f"    Discovered {len(campus_intern_cards)} existing internship card(s) on Naukri Campus.")
        for i, card in enumerate(campus_intern_cards):
            try:
                card_text = card.inner_text()
                company = card.locator("p.card-heading").first.inner_text().strip() if card.locator("p.card-heading").count() else ""
                tenure = card.locator("p.card-sub-heading").first.inner_text().strip() if card.locator("p.card-sub-heading").count() else ""
                designation = ""
                live_desc = ""

                # Inspect modal with isolated container scrolling to avoid background page leaks
                edit_pencil = card.locator("span.new-pencil").first
                if edit_pencil.count() > 0 and edit_pencil.is_visible():
                    edit_pencil.click(force=True)
                    page.wait_for_timeout(1000)
                    desig_inp = page.locator("input#projectName0, input[name*='projectName']").first
                    if desig_inp.count() > 0:
                        designation = desig_inp.input_value() or desig_inp.get_attribute("value") or ""
                    desc_inp = page.locator("textarea#details0, textarea[name*='details']").first
                    if desc_inp.count() > 0:
                        live_desc = desc_inp.input_value() or desc_inp.inner_text() or ""

                    # Close modal cleanly without background scroll
                    cancel_link = page.locator("#internshipDetails_Modal .btn-container span:has-text('Cancel'), #internshipDetails_Modal span:has-text('Cancel')").first
                    if cancel_link.count() > 0:
                        cancel_link.click(force=True)
                    else:
                        page.keyboard.press("Escape")
                    page.wait_for_timeout(400)

                live_employments.append({
                    "index": len(live_employments),
                    "company": company.strip(),
                    "designation": designation.strip(),
                    "tenure": tenure.strip(),
                    "description": live_desc.strip(),
                    "raw_text": card_text,
                    "is_campus_internship": True
                })
                log(f"      - Live Campus Internship #{i+1}: '{designation or 'Intern'}' at '{company}' [{tenure}] (Desc: {len(live_desc)} chars)")
            except Exception as e:
                log(f"      [!] Error reading campus internship card {i}: {e}")

    return {
        "headline": live_headline,
        "summary": live_summary,
        "skills": live_skills,
        "employments": live_employments
    }

def upload_resume(page, profile_dir: Path):
    log("\n[STEP E.4] Checking Tailored Resume PDF Injection...")
    manifest_path = profile_dir / "output" / "search_manifest.json"
    resume_to_upload = None

    if manifest_path.exists():
        try:
            manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
            if manifest and isinstance(manifest, list) and len(manifest) > 0 and "tailored_pdf" in manifest[0]:
                resume_to_upload = manifest[0]["tailored_pdf"]
        except Exception:
            pass

    if not resume_to_upload or not os.path.exists(resume_to_upload):
        cand_pdfs = list(profile_dir.glob("*_Resume.pdf"))
        if cand_pdfs:
            resume_to_upload = str(cand_pdfs[0].resolve())

    if resume_to_upload and os.path.exists(resume_to_upload):
        try:
            page.goto("https://www.naukri.com/mnjuser/profile", wait_until="domcontentloaded")
            page.wait_for_timeout(2500)
            file_input = page.locator("input#attachCV, input[type='file']").first
            if file_input.count() > 0:
                file_input.set_input_files(resume_to_upload)
                page.wait_for_timeout(4000)
                log(f"    [OK] Embedded ATS Resume into profile: {os.path.basename(resume_to_upload)}")
        except Exception as e:
            log(f"    [!] Failed to upload resume: {e}")
    else:
        log("    [SKIP] No tailored resume PDF found to upload.")

def generate_robust_about_section(resume_text: str, ai_client: AIClient) -> str:
    """Uses centralized AIClient to generate a polished LinkedIn summary."""
    if not resume_text:
        return ""
    log("[Brain] Analyzing resume to generate a robust LinkedIn About summary...")
    prompt = f"""
You are an expert Executive Resume Writer. Analyze the following candidate resume and write a robust, highly professional, and engaging LinkedIn 'About' summary.
Do NOT use first-person pronouns like "I" excessively. Keep it under 2000 characters. Focus on their core achievements, domains of expertise, and overall value proposition.

RESUME:
{resume_text}

Output ONLY the final summary text. No introductions or explanations.
"""
    return ai_client.generate_text(prompt)

