class ChatbotResolver:
    """
    DOM Chatbot Reverse-Engineering Engine for Naukri and platform modals.
    Implements Guardrails C7, C8, C9, H1, H2, H3, H5, H6.
    """
    CHIP_SELECTORS = (
        "div.radioItem, div.choiceChip, div.clickableChip, div.optionItem, "
        "div[class*='radioItem'], label[class*='radio'], ul.ChoiceList li, "
        "div[class*='chipItem'], button[class*='chip'], span[class*='chip'], "
        "button[class*='option'], li[class*='option'], div.customRadio, "
        ".chatbot_Choice, button.radio-button, span.radio-button, label.ssrc__label"
    )

    def __init__(self, page, ctx: ProfileContext, ai_client: AIClient):
        self.page = page
        self.ctx = ctx
        self.ai = ai_client
        self.config = getattr(ctx, "config", {})
        cand = self.config.get("candidate", {})

        self.candidate_name = getattr(ctx, "candidate_name", None) or cand.get("full_name") or cand.get("name") or ""
        self.first_name = getattr(ctx, "first_name", None) or (self.candidate_name.split()[0] if self.candidate_name else "")
        self.resume_text = getattr(ctx, "resume_text", "")

    def get_drawer(self):
        """Returns the active Playwright locator for the chatbot drawer container."""
        drawer_selectors = [
            ".chatbot_DrawerContentWrapper",
            "div[class*='chatbot_Drawer']",
            "div[class*='_chatbotContainer']",
            "div[class*='chatbot_MessageContainer']",
            "div[id*='Messages']"
        ]
        for sel in drawer_selectors:
            loc = self.page.locator(sel).first
            if loc.count() > 0 and loc.is_visible():
                return loc
        return self.page.locator(".chatbot_DrawerContentWrapper").first

    def is_drawer_open(self) -> bool:
        drawer_selectors = [
            ".chatbot_DrawerContentWrapper",
            "div[class*='chatbot_Drawer']",
            "div[class*='_chatbotContainer']",
            "div[class*='chatbot_MessageContainer']",
            "div[id*='Messages']"
        ]
        for sel in drawer_selectors:
            loc = self.page.locator(sel)
            if loc.count() > 0 and loc.first.is_visible():
                return True
        return False

    def scroll_drawer_to_bottom(self) -> None:
        """Scrolls strictly the inner message container of the drawer, never window or document."""
        scroll_script = """
        () => {
            const container = document.querySelector(
                '.chatbot_MessageContainer, div[class*="MessageContainer"], div[id*="Messages"]'
            );
            if (container) {
                container.scrollTop = container.scrollHeight;
                return true;
            }
            return false;
        }
        """
        try:
            self.page.evaluate(scroll_script)
            self.page.wait_for_timeout(300)
        except Exception:
            pass

    def extract_active_question(self) -> Tuple[Optional[str], Optional[str]]:
        self.scroll_drawer_to_bottom()

        bot_items = self.page.locator(
            "div[class*='chatbot_MessageContainer'] li.botItem, "
            "div[id*='Messages'] li.botItem, "
            ".chatbot_DrawerContentWrapper li.botItem, "
            "li.botItem.chatbot_ListItem, "
            "li.botItem"
        )
        count = bot_items.count()
        if count == 0:
            return None, None

        raw_messages = []
        for i in range(count):
            item = bot_items.nth(i)
            msg_div = item.locator(".botMsg, div[class*='botMsg']").first
            if msg_div.count() > 0:
                txt = msg_div.inner_text().strip()
                if txt:
                    raw_messages.append(txt)

        if not raw_messages:
            return None, None

        cand_name_clean = self.candidate_name.lower().strip()
        first_name_clean = self.first_name.lower().strip()

        greeting_markers = [
            "thank you for showing interest",
            "kindly answer all",
            "answer all the recruiter",
            "welcome to",
            "to successfully apply",
            "hi ",
            "hello "
        ]

        completion_markers = [
            "thank you for your response",
            "thank you for your responses",
            "thank you for answering",
            "thank you for response",
            "responses recorded",
            "responses have been recorded",
            "your responses have been recorded",
            "application has been submitted",
            "applied successfully"
        ]

        active_question = None
        filtered_greeting = None

        for msg in reversed(raw_messages):
            msg_lower = msg.lower()
            is_non_question = False

            if (first_name_clean and first_name_clean in msg_lower) or (cand_name_clean and cand_name_clean in msg_lower):
                if any(marker in msg_lower for marker in greeting_markers):
                    is_non_question = True
                    filtered_greeting = msg
            elif any(marker in msg_lower for marker in greeting_markers):
                is_non_question = True
                filtered_greeting = msg
            elif any(marker in msg_lower for marker in completion_markers):
                is_non_question = True

            if not is_non_question and len(msg.strip()) > 3:
                active_question = msg.strip()
                break

        return active_question, filtered_greeting

    def detect_ui_control(self) -> str:
        drawer = self.page.locator(".chatbot_DrawerContentWrapper, div[class*='chatbot_Drawer'], div[class*='_chatbotContainer']").first

        # 1. File Upload
        file_input = drawer.locator("input[type='file'], input.chatbot_Uploader, input[id*='Uploader']")
        if file_input.count() > 0 and file_input.first.is_visible():
            return "FILE_UPLOAD"

        # 2. Date Input
        date_input = drawer.locator("input[type='date'], input.datePicker, input[class*='datePicker'], input[class*='date-picker']")
        if date_input.count() > 0 and date_input.first.is_visible():
            return "DATE_INPUT"

        # 3. Radio / Choice Chips / Custom Radios (Strictly ignoring .chipMsg)
        is_radio = self.page.evaluate("""() => {
            const drawer = document.querySelector('.chatbot_DrawerContentWrapper, div[class*="_chatbotContainer"]') || document;
            if (drawer.querySelector('input[type="radio"], input[type="checkbox"]')) return true;

            const chips = Array.from(drawer.querySelectorAll(
                '.choiceChip, .clickableChip, .radioItem, .optionItem, [class*="chipItem"], ' +
                'label.ssrc__label, div.customRadio, div.radioItem, div.togglePill, button.toggle, ' +
                'div[class*="toggle"], div.yesNoToggle, label[class*="radio"], ul.ChoiceList li'
            )).filter(el => !el.closest('.chipMsg') && !el.classList.contains('chipMsg') && el.offsetParent !== null);

            const nonSkipChips = chips.filter(el => {
                const t = (el.innerText || '').toLowerCase().trim();
                return !t.startsWith('skip') && !t.includes('skip this question') && !t.includes('restart');
            });
            const hasTextarea = !!drawer.querySelector('div.textArea[contenteditable="true"], div[id^="userInput_"]');
            if (chips.length > 0 && nonSkipChips.length === 0 && hasTextarea) {
                return false;
            }
            return chips.length > 0;
        }""")
        if is_radio:
            return "RADIO_CHIP"

        # 4. Dropdowns
        select_dropdown = drawer.locator("select, div.custom-select, div[class*='dropdown'], div[class*='select-dropdown']")
        if select_dropdown.count() > 0 and select_dropdown.first.is_visible():
            return "DROPDOWN"

        # 5. Contenteditable Text Inputs
        textarea = drawer.locator(
            "div.textArea[contenteditable='true'], "
            "div[id^='userInput_'], "
            "div[id*='userInput'], "
            ".textAreaWrapper div[contenteditable='true'], "
            "div.chatbot_userInput, "
            "input[type='text'], "
            "textarea"
        )
        if textarea.count() > 0 and textarea.first.is_visible():
            return "CONTENTEDITABLE"

        body_textarea = self.page.locator("div.textArea[contenteditable='true'], div[id^='userInput_']").first
        if body_textarea.count() > 0 and body_textarea.is_visible():
            return "CONTENTEDITABLE"

        return "UNKNOWN"

    def get_radio_options(self) -> List[str]:
        try:
            options = self.page.evaluate(r"""() => {
                try {
                    const drawer = document.querySelector('.chatbot_DrawerContentWrapper, div[class*="_chatbotContainer"]') || document;
                    const opts = new Set();

                    // Strategy A: Explicit Radio Inputs
                    const radios = drawer.querySelectorAll('input[type="radio"], input[type="checkbox"]');
                    if (radios.length > 0) {
                        radios.forEach(r => {
                            if (r.closest('.chipMsg')) return;
                            if (r.id) {
                                try {
                                    const escapedId = (window.CSS && CSS.escape) ? CSS.escape(r.id) : r.id.replace(/([ #;&,.+*~\':"!^$[\]()=>|/@])/g, '\\$1');
                                    const label = drawer.querySelector(`label[for="${escapedId}"]`);
                                    if (label && label.innerText) {
                                        opts.add(label.innerText.trim());
                                        return;
                                    }
                                } catch (e) {}
                            }
                            if (r.nextElementSibling && (r.nextElementSibling.tagName === 'LABEL' || r.nextElementSibling.tagName === 'SPAN')) {
                                opts.add(r.nextElementSibling.innerText.trim());
                                return;
                            }
                            if (r.value && r.value.length > 0 && r.value !== 'on') {
                                opts.add(r.value.trim());
                            }
                        });
                    }

                    // Strategy B: Choice Chips and Custom Radio Wrappers
                    const chips = drawer.querySelectorAll(
                        '.choiceChip, .clickableChip, .radioItem, .optionItem, [class*="chipItem"], ' +
                        'label.ssrc__label, div.customRadio, div.togglePill, button.toggle, div.yesNoToggle, ' +
                        'label[class*="radio"], ul.ChoiceList li'
                    );
                    chips.forEach(c => {
                        if (c.closest('.chipMsg') || c.classList.contains('chipMsg')) return;
                        const txt = c.innerText.trim();
                        if (txt && txt.length < 150 && !txt.includes('\n')) {
                            opts.add(txt);
                        }
                    });

                    return Array.from(opts).filter(Boolean);
                } catch (err) {
                    return [];
                }
            }""")
            return options if isinstance(options, list) else []
        except Exception as e:
            log_step("WARNING", f"Exception during get_radio_options evaluation: {e}")
            return []

    def resolve_answer(self, question: str, options: Optional[List[str]] = None, control_type: str = "CONTENTEDITABLE") -> str:
        q_clean = question.strip()
        log_step("AI BRAIN", f"Grounded Resume Analysis -> Resolving screening question...")
        ai_response = self.ai.answer_screening_question(
            question=q_clean,
            candidate_profile=self.config,
            options=options,
            control_type=control_type,
            resume_text=self.resume_text
        )
        cleaned_ans = ai_response.strip().strip('"').strip("'")
        log_step("AI BRAIN", f"Resolved Factual Answer: '{cleaned_ans}'")
        return cleaned_ans

    def adapt_answer_format(self, question: str, previous_ans: str, attempt: int) -> str:
        """
        Adaptive Retry Formatter (C7 & H6):
        When a question is repeated (stuck_count >= 1), the previous answer was likely
        rejected by portal frontend validation (e.g. '9' vs '9 years', or '30' vs '30 Days').
        Adapts format according to question semantics and retry attempt count.
        """
        if not previous_ans:
            return previous_ans

        q_lower = question.lower()
        ans_clean = str(previous_ans).strip()
        num_match = re.match(r'^(\d+(?:\.\d+)?)$', ans_clean)

        # A. Experience-related questions
        if any(w in q_lower for w in ["experience", "exp", "years", "working", "work ex"]):
            if num_match:
                val = num_match.group(1)
                int_val = int(float(val)) if float(val).is_integer() else val
                if attempt == 1:
                    return f"{int_val} years"
                elif attempt >= 2:
                    return f"{int_val} Yrs"
            elif any(w in ans_clean.lower() for w in ["years", "yr", "yrs"]):
                m = re.search(r'\d+(?:\.\d+)?', ans_clean)
                if m:
                    return m.group(0)

        # B. Notice period questions
        elif any(w in q_lower for w in ["notice", "np", "serving", "lwd", "last working"]):
            if num_match:
                val = num_match.group(1)
                if attempt == 1:
                    return f"{val} Days"
                elif attempt >= 2:
                    return f"{val} days"
            elif "days" in ans_clean.lower() or "day" in ans_clean.lower():
                m = re.search(r'\d+', ans_clean)
                if m:
                    return m.group(0)

        # C. Salary / CTC questions
        elif any(w in q_lower for w in ["ctc", "salary", "compensation", "package", "lakhs", "inr"]):
            if num_match:
                val = float(num_match.group(1))
                if attempt == 1:
                    return f"{int(val) if val.is_integer() else val} LPA"
                elif attempt >= 2:
                    return f"{int(val * 100000)}"
            elif "lpa" in ans_clean.lower():
                m = re.search(r'\d+(?:\.\d+)?', ans_clean)
                if m:
                    return m.group(0)

        # D. Generic unit stripping if words and digits both present
        if re.search(r'[a-zA-Z]', ans_clean) and re.search(r'\d', ans_clean):
            m = re.search(r'\d+(?:\.\d+)?', ans_clean)
            if m:
                return m.group(0)

        return ans_clean

    def _get_input_field(self):
        drawer = self.get_drawer()
        selectors = [
            "div.textArea[contenteditable='true']",
            "div[id*='userInput']",
            "div.chatbot_SendMessageContainer div.textArea",
            "div[id*='InputBox'] div.textArea",
            "div.textAreaWrapper div[contenteditable='true']",
            "div.chatbot_InputContainer div.textArea",
            "textarea.chatbot_Input",
            "input.chatbot_Input"
        ]
        for sel in selectors:
            loc = drawer.locator(sel).first
            try:
                if loc.is_visible(timeout=400):
                    return loc
            except Exception:
                continue
        return None

    def execute_contenteditable_input(self, answer: str) -> bool:
        input_loc = self._get_input_field()
        if not input_loc:
            log_step("WARNING", "Could not locate contenteditable textarea in chatbot drawer.")
            return False

        if not answer or not str(answer).strip():
            log_step("WARNING", "Attempted contenteditable input with empty answer string. Aborting typing.")
            return False

        log_step("CHATBOT", f"Targeting input container with answer: '{answer}'")
        self.scroll_drawer_to_bottom()

        try:
            input_loc.click(force=True)
            human_jitter(100, 250)
            mod_key = "Meta+A" if sys.platform == "darwin" else "Control+A"
            self.page.keyboard.press(mod_key)
            self.page.keyboard.press("Backspace")
            human_jitter(50, 150)

            self.page.keyboard.insert_text(str(answer))
            human_jitter(100, 200)

            js_dispatch = """
            (ans) => {
                const drawer = document.querySelector('.chatbot_DrawerContentWrapper, div[class*="_chatbotContainer"], div[class*="chatbot_Drawer"]');
                const root = drawer || document;
                const el = root.querySelector(
                    'div.textArea[contenteditable="true"], div[id*="userInput"], .textAreaWrapper div[contenteditable="true"]'
                );
                if (el) {
                    el.focus();
                    if (!el.innerText || el.innerText.trim() === '') {
                        document.execCommand('insertText', false, ans);
                    }
                    el.dispatchEvent(new Event('input', { bubbles: true }));
                    el.dispatchEvent(new Event('change', { bubbles: true }));
                    el.dispatchEvent(new KeyboardEvent('keydown', { bubbles: true, key: 'Enter' }));
                    el.dispatchEvent(new KeyboardEvent('keyup', { bubbles: true, key: 'Enter' }));
                }

                if (drawer) {
                    const btn = drawer.querySelector('.sendMsgbtn_container .sendMsg, div[id*="sendMsg"] .sendMsg, .sendMsg');
                    if (btn) {
                        btn.classList.remove('disabled');
                        btn.removeAttribute('disabled');
                    } else {
                        const btns = drawer.querySelectorAll('button');
                        for (let b of btns) {
                            let t = (b.innerText || '').toLowerCase();
                            if (t.includes('save') || t.includes('send') || t.includes('submit')) {
                                b.classList.remove('disabled');
                                b.removeAttribute('disabled');
                                break;
                            }
                        }
                    }
                }
                return true;
            }
            """
            self.page.evaluate(js_dispatch, str(answer))
            human_jitter(150, 300)

            drawer = self.get_drawer()
            send_btn_selectors = [
                ".sendMsgbtn_container .sendMsg",
                "div[id*='sendMsg'] .sendMsg",
                ".sendMsgbtn_container div.send .sendMsg",
                "span.chatBot-send",
                "span[class*='send']",
                "button[class*='send']",
                "button[class*='save']",
                "button:has-text('Save')",
                "button:has-text('Submit')"
            ]

            clicked = False
            for btn_sel in send_btn_selectors:
                btn_loc = drawer.locator(btn_sel).first
                if btn_loc.count() > 0 and btn_loc.is_visible():
                    btn_loc.click(force=True)
                    clicked = True
                    break

            if not clicked:
                self.page.keyboard.press("Enter")

            self.page.wait_for_timeout(1500)
            return True
        except Exception as e:
            log_step("WARNING", f"Failed typing into input container: {e}")
            return False

    def execute_chip_selection(self, matched_option: str) -> bool:
        if not matched_option or not str(matched_option).strip():
            log_step("WARNING", "Attempted chip selection with empty option string. Aborting click.")
            return False
        self.scroll_drawer_to_bottom()
        drawer = self.get_drawer()

        # Support multi-select options (e.g. "Python, SQL" or "Immediate, Serving Notice")
        raw_options = [o.strip() for o in re.split(r'[,;]+', str(matched_option)) if o.strip()]
        if not raw_options:
            return False

        any_clicked = False

        for clean_target in raw_options:
            if not clean_target:
                continue
            clicked = self.page.evaluate("""(targetText) => {
                const cleanTarget = (targetText || '').toLowerCase().trim();
                if (!cleanTarget) return false;
                const drawer = document.querySelector('.chatbot_DrawerContentWrapper, div[class*="_chatbotContainer"], div[class*="chatbot_Drawer"]');
                if (!drawer) return false;

                // Priority 0: Exact Naukri radio and checkbox labels (.ssrc__label, .ssrc__radio, .ssrc__checkbox)
                const ssrcLabels = drawer.querySelectorAll(
                    '.singleselect-radiobutton-container label, .multiselect-checkbox-container label, ' +
                    '.ssrc__radio-btn-container label, .ssrc__checkbox-btn-container label, label.ssrc__label'
                );
                for (let lbl of ssrcLabels) {
                    const txt = (lbl.innerText || '').toLowerCase().trim();
                    if (cleanTarget && (txt === cleanTarget || txt.includes(cleanTarget) || cleanTarget.includes(txt))) {
                        lbl.click();
                        const inputId = lbl.getAttribute('for');
                        if (inputId) {
                            let inputEl = document.getElementById(inputId);
                            if (!inputEl && window.CSS && CSS.escape) {
                                try { inputEl = drawer.querySelector('#' + CSS.escape(inputId)); } catch(e) {}
                            }
                            if (inputEl) {
                                inputEl.checked = true;
                                inputEl.dispatchEvent(new Event('change', {bubbles: true}));
                                inputEl.dispatchEvent(new Event('input', {bubbles: true}));
                            }
                        }
                        return true;
                    }
                }

                // 1. Check general labels and their associated inputs inside drawer
                const labels = drawer.querySelectorAll('label');
                for (let lbl of labels) {
                    if (lbl.closest('.chipMsg') || lbl.classList.contains('chipMsg')) continue;
                    const txt = (lbl.innerText || '').toLowerCase().trim();
                    if (txt === cleanTarget || txt.includes(cleanTarget) || cleanTarget.includes(txt)) {
                        lbl.click();
                        const inputId = lbl.getAttribute('for');
                        if (inputId) {
                            let inputEl = document.getElementById(inputId);
                            if (!inputEl && window.CSS && CSS.escape) {
                                try { inputEl = drawer.querySelector('#' + CSS.escape(inputId)); } catch(e) {}
                            }
                            if (inputEl) {
                                if (inputEl.type === 'checkbox') {
                                    if (!inputEl.checked) {
                                        inputEl.checked = true;
                                        inputEl.dispatchEvent(new Event('change', {bubbles: true}));
                                        inputEl.dispatchEvent(new Event('input', {bubbles: true}));
                                    }
                                } else if (inputEl.type === 'radio') {
                                    inputEl.checked = true;
                                    inputEl.dispatchEvent(new Event('change', {bubbles: true}));
                                    inputEl.dispatchEvent(new Event('input', {bubbles: true}));
                                }
                            }
                        }
                        return true;
                    }
                }

                // 2. Direct inputs with adjacent text inside drawer
                const inputs = drawer.querySelectorAll('input[type="checkbox"], input[type="radio"], input.ssrc__radio, input.ssrc__checkbox');
                for (let inp of inputs) {
                    if (inp.closest('.chipMsg')) continue;
                    let labelText = "";
                    if (inp.id) {
                        const l = drawer.querySelector(`label[for="${inp.id}"]`);
                        if (l) labelText = (l.innerText || '').toLowerCase().trim();
                    }
                    if (!labelText && inp.nextElementSibling) {
                        labelText = (inp.nextElementSibling.innerText || '').toLowerCase().trim();
                    }
                    if (cleanTarget && labelText && (labelText === cleanTarget || labelText.includes(cleanTarget) || cleanTarget.includes(labelText))) {
                        inp.click();
                        inp.checked = true;
                        inp.dispatchEvent(new Event('change', {bubbles: true}));
                        inp.dispatchEvent(new Event('input', {bubbles: true}));
                        return true;
                    }
                }

                // 3. Custom chip elements inside drawer
                const elements = drawer.querySelectorAll(
                    'div.choiceChip, div.clickableChip, div.radioItem, div.optionItem, ' +
                    'div[class*="chipItem"], span[class*="chip"], button[class*="chip"], ' +
                    'div.customRadio, div.togglePill, button.toggle, div.yesNoToggle, ' +
                    'ul.ChoiceList li, span, div, button'
                );
                for (let el of elements) {
                    if (el.closest('.chipMsg') || el.classList.contains('chipMsg')) continue;
                    if (el.children.length > 2) continue;
                    let text = (el.innerText || '').toLowerCase().trim();

                    if (text === cleanTarget || (text && cleanTarget && text === cleanTarget)) {
                        el.click();
                        return true;
                    }
                }
                return false;
            }""", clean_target)

            if not clicked:
                try:
                    escaped_text = clean_target.replace("'", "\\'")
                    chip_loc = drawer.locator(
                        f"label.ssrc__label:has-text('{escaped_text}'), label:has-text('{escaped_text}'), "
                        f"button:has-text('{escaped_text}'), div.clickableChip:has-text('{escaped_text}'), "
                        f"div.choiceChip:has-text('{escaped_text}'), div.radioItem:has-text('{escaped_text}'), span:has-text('{escaped_text}')"
                    ).first
                    if chip_loc.count() > 0 and chip_loc.is_visible():
                        chip_loc.click(force=True)
                        clicked = True
                except Exception:
                    pass

            if clicked:
                any_clicked = True
                self.page.wait_for_timeout(300)

        if any_clicked:
            self.page.wait_for_timeout(500)

            # Commit drawer selection: Find Save/Submit/Next button STRICTLY inside drawer
            submit_clicked = self.page.evaluate("""() => {
                const drawer = document.querySelector('.chatbot_DrawerContentWrapper, div[class*="_chatbotContainer"], div[class*="chatbot_Drawer"]');
                if (!drawer) return false;

                // Priority 1: .sendMsg element inside drawer
                const sendBtn = drawer.querySelector('.sendMsgbtn_container .sendMsg, div[id*="sendMsg"] .sendMsg, .sendMsg');
                if (sendBtn) {
                    const parentSend = sendBtn.closest('.send') || sendBtn.parentElement;
                    if (parentSend) {
                        parentSend.classList.remove('disabled');
                        parentSend.removeAttribute('disabled');
                    }
                    sendBtn.classList.remove('disabled');
                    sendBtn.removeAttribute('disabled');
                    sendBtn.click();
                    return true;
                }

                // Priority 2: Action buttons strictly inside drawer footer
                const drawerBtns = drawer.querySelectorAll(
                    '.footerWrapper button, .chatbot_Footer button, div[class*="Footer"] button, ' +
                    'button[class*="save"], button[class*="submit"], button[class*="next"]'
                );
                for (let btn of drawerBtns) {
                    if (!drawer.contains(btn)) continue;
                    let t = (btn.innerText || '').toLowerCase();
                    if (t.includes('save') || t.includes('submit') || t.includes('next') || t.includes('continue')) {
                        btn.click();
                        return true;
                    }
                }

                // Priority 3: Any enabled button strictly inside drawer with save/submit/next
                const allDrawerBtns = drawer.querySelectorAll('button');
                for (let btn of allDrawerBtns) {
                    if (!drawer.contains(btn)) continue;
                    let t = (btn.innerText || '').toLowerCase();
                    if (t.includes('save') || t.includes('submit') || t.includes('next')) {
                        btn.click();
                        return true;
                    }
                }
                return false;
            }""")

            if not submit_clicked:
                drawer_save_selectors = [
                    ".sendMsgbtn_container .sendMsg",
                    "div[id*='sendMsg'] .sendMsg",
                    "button[class*='save']",
                    "button[class*='submit']",
                    "button:has-text('Save')",
                    "button:has-text('Submit')",
                    "button:has-text('Next')"
                ]
                for s_sel in drawer_save_selectors:
                    btn = drawer.locator(s_sel).first
                    try:
                        if btn.count() > 0 and btn.is_visible():
                            btn.click(force=True)
                            submit_clicked = True
                            break
                    except Exception:
                        pass

            self.page.wait_for_timeout(800)
            return True

        log_step("WARNING", f"Could not click element for option: '{matched_option}'")
        return False

    def execute_file_upload(self, tailored_pdf_path: Optional[str] = None) -> bool:
        drawer = self.get_drawer()
        file_input = drawer.locator("input[type='file'], input.chatbot_Uploader, input[id*='Uploader']").first

        if file_input.count() == 0:
            return False

        target_pdf = tailored_pdf_path
        if not target_pdf or not os.path.exists(target_pdf):
            profile_pdf = self.ctx.profile_dir / f"{self.candidate_name.replace(' ', '_')}_Resume.pdf"
            if profile_pdf.exists():
                target_pdf = str(profile_pdf)

        if not target_pdf or not os.path.exists(target_pdf):
            log_step("CHATBOT", "No valid PDF resume file found on disk for upload.")
            return False

        log_step("CHATBOT", f"Uploading resume PDF: {target_pdf}")
        file_input.set_input_files(target_pdf)
        self.page.wait_for_timeout(2000)
        return True

    def check_completion_status(self) -> Tuple[bool, str]:
        success_markers = [
            "applied successfully",
            "application has been submitted",
            "your application has reached",
            "successfully applied",
            "application submitted",
            "application sent to recruiter",
            "responses recorded",
            "responses have been recorded",
            "profile shared with recruiter",
            "has reached the recruiter",
            "application sent",
            "your application was sent",
            "already applied",
            "applied on",
            "you have applied to this vacancy",
            "you have applied"
        ]

        drawer = self.page.locator(".chatbot_DrawerContentWrapper, div[class*='chatbot_Drawer'], div[class*='_chatbotContainer']").first
        if drawer.count() > 0 and drawer.is_visible():
            drawer_text = drawer.inner_text().lower()
            for marker in success_markers:
                if marker in drawer_text:
                    return True, f"Detected success marker in drawer: '{marker}'"
            return False, ""

        page_text = self.page.locator("body").inner_text().lower()
        for marker in success_markers:
            if marker in page_text:
                return True, f"Detected success marker on page: '{marker}'"

        applied_selectors = [
            "button.applied-txt",
            "span.already-applied",
            "div.apply-message",
            "button#apply-button:has-text('Applied')",
            "button:has-text('Applied')",
            "span:has-text('Applied')",
            ".already-applied"
        ]
        for sel in applied_selectors:
            try:
                el = self.page.locator(sel).first
                if el.count() > 0 and el.is_visible():
                    return True, f"Detected applied status indicator on page: '{sel}'"
            except Exception:
                pass

        return False, ""


