def clean_json(text):
    t = text.strip()
    if t.startswith("`"):
        t = "\n".join(l for l in t.split("\n") if not l.strip().startswith("`")).strip()
    return t

class JobBoardScraper(ABC):
    def __init__(self, ctx, page, browser):
        self.ctx = ctx
        self.page = page
        self.browser = browser
        self.logger = ctx.logger

    def random_sleep(self, min_s: float = 1.0, max_s: float = 3.0):
        time.sleep(random.uniform(min_s, max_s))

    @abstractmethod
    def scrape_jobs(self) -> List[Dict[str, Any]]:
        pass

class LinkedInScraper(JobBoardScraper):
    def build_urls(self):
        urls = []
        kw_str = quote_plus(" ".join(self.ctx.target_keywords[:4]))
        for loc in (self.ctx.target_locations or []):
            urls.append((f"https://www.linkedin.com/jobs/search/?f_AL=true&keywords={kw_str}&location={quote_plus(loc)}", loc))
        return urls

    def scrape_jobs(self):
        urls = self.build_urls()
        results = []
        for search_url, location in urls:
            self.logger.info(f"[LINKEDIN] Searching: {location}...")
            try:
                self.page.goto(search_url, wait_until="domcontentloaded", timeout=40000)
                self.random_sleep(3, 5)
                cards = self.page.locator("div.job-card-container").all()
                self.logger.info(f"  Found {len(cards)} candidate cards.")

                for card in cards[:4]:
                    card.scroll_into_view_if_needed()
                    self.random_sleep(0.5, 1)
                    card.click()
                    self.random_sleep(1, 2)

                    title = card.locator(".job-card-list__title").first.inner_text().strip()
                    company = card.locator(".job-card-container__primary-description").first.inner_text().strip()

                    jd_elem = self.page.locator(".jobs-description-content, .job-description").first
                    jd_text = jd_elem.inner_text() if jd_elem.is_visible() else f"{title} at {company}"

                    results.append({
                        "title": title, "company": company, "location": location,
                        "url": self.page.url, "platform": "linkedin", "jd_text": jd_text
                    })
            except Exception as e:
                self.logger.error(f"  [!] LinkedIn Error: {e}")
        return results

class NaukriScraper(JobBoardScraper):
    def build_urls(self):
        urls = []
        for kw in self.ctx.target_keywords[:3]:
            slug = "-".join(kw.lower().split())
            for loc in (self.ctx.target_locations or []):
                loc_slug = loc.lower().replace(" ", "-")
                urls.append((f"https://www.naukri.com/{slug}-jobs-in-{loc_slug}", loc, kw))
        return urls

    def scrape_jobs(self):
        urls = self.build_urls()
        results = []
        seen = set()

        for search_url, location, keyword in urls:
            self.logger.info(f"[NAUKRI] Searching: '{keyword}' in {location}...")
            try:
                self.page.goto(search_url, wait_until="domcontentloaded", timeout=40000)
                self.random_sleep(3, 5)
                cards = self.page.locator("div.srp-jobtuple-wrapper").all()
                self.logger.info(f"  Found {len(cards)} candidate cards.")

                for card in cards[:4]:
                    title_elem = card.locator("a.title").first
                    title = title_elem.inner_text().strip()
                    job_url = title_elem.get_attribute("href")

                    if job_url in seen: continue
                    seen.add(job_url)

                    comp_elem = card.locator("a.comp-name").first
                    company = comp_elem.inner_text().strip() if comp_elem.is_visible() else "Target Company"

                    jd_text = f"{title} at {company}"
                    if job_url:
                        # FIXED: Use self.page.context instead of self.browser.contexts[0]
                        detail_page = self.page.context.new_page()
                        try:
                            detail_page.goto(job_url, wait_until="domcontentloaded", timeout=20000)
                            self.random_sleep(1, 2)
                            jd_elem = detail_page.locator(".job-desc, .jd-container").first
                            if jd_elem.is_visible(): jd_text = jd_elem.inner_text().strip()
                        except: pass
                        finally: detail_page.close()

                    results.append({
                        "title": title, "company": company, "location": location,
                        "url": job_url, "platform": "naukri", "jd_text": jd_text
                    })
            except Exception as e:
                self.logger.error(f"  [!] Naukri Error: {e}")
        return results

class BrowserManager:
    """
    Manages Playwright connection to an active Chrome instance via CDP.
    """

    def __init__(self, cdp_url: str = None):
        self.cdp_url = cdp_url or os.environ.get("CDP_URL")
        self.playwright = None
        self.browser: Optional[Browser] = None
        self.context: Optional[BrowserContext] = None

    def start(self) -> BrowserContext:
        """Starts Playwright and connects to Chrome over CDP."""
        if not self.playwright:
            self.playwright = sync_playwright().start()

        if not self.browser or not self.browser.is_connected():
            try:
                self.browser = self.playwright.chromium.connect_over_cdp(self.cdp_url)
            except Exception as e:
                raise RuntimeError(
                    f"[BrowserManager] Failed to connect to Chrome at {self.cdp_url}. "
                    f"Ensure Chrome is initialized with the correct remote-debugging-port. Error: {e}"
                )

        if self.browser.contexts:
            self.context = self.browser.contexts[0]
        else:
            self.context = self.browser.new_context()

        return self.context

    def get_context(self) -> BrowserContext:
        """Returns the active browser context, initializing if necessary."""
        if not self.context or not self.browser or not self.browser.is_connected():
            return self.start()
        return self.context

    def new_page(self) -> Page:
        """Creates and returns a fresh, dedicated browser page in the CDP context."""
        context = self.get_context()
        page = context.new_page()
        page.bring_to_front()
        return page

    def close(self):
        """Closes Playwright connection cleanly without terminating user's Chrome instance."""
        try:
            if self.playwright:
                self.playwright.stop()
                self.playwright = None
                self.browser = None
                self.context = None
        except Exception:
            pass

def get_browser_context(cdp_url: str = None) -> BrowserContext:
    """Functional helper for legacy cross-script invocations."""
    manager = BrowserManager(cdp_url=cdp_url)
    return manager.get_context()

def extract_platform_job_id(url: str, platform: str = "") -> Optional[str]:
    """
    Extracts immutable numeric platform job ID for deduplication across query/slug changes.
    Naukri: Trailing 10-14 digit identifier in slug (e.g. -040926031442) -> 'naukri:040926031442'
    LinkedIn: /jobs/view/<id> or currentJobId=<id> -> 'linkedin:<id>'
    """
    if not url:
        return None
    url_str = str(url).strip().lower()
    if "naukri.com" in url_str or platform.lower() == "naukri":
        m = re.search(r'-(\d{10,14})(?:[/?#]|$)', url_str)
        if m:
            return f"naukri:{m.group(1)}"
    if "linkedin.com" in url_str or platform.lower() == "linkedin":
        m = re.search(r'(?:/jobs/view/|currentjobid=)(\d+)', url_str)
        if m:
            return f"linkedin:{m.group(1)}"
    return None

class ProcessedLedger(dict):
    """
    High-performance hybrid ledger mapping URL/composite key -> structured metadata.
    Subclasses dict for O(1) key lookups, structured inspection, and JSON serialization,
    while offering backward-compatible set APIs (.add, .union, .intersection, .difference).
    Automatically indexes canonical URLs and platform job IDs for zero-duplicate guarantees.
    """
    def __init__(self, *args, **kwargs):
        super().__init__()
        if args and isinstance(args[0], dict):
            for k, v in args[0].items():
                if k:
                    clean_k = str(k).lower().strip()
                    super().__setitem__(clean_k, v if isinstance(v, dict) else {"status": str(v)})
        elif args and isinstance(args[0], (list, set, tuple)):
            for item in args[0]:
                if item:
                    self.add(str(item).lower().strip(), status="legacy")
        if kwargs:
            for k, v in kwargs.items():
                if k:
                    clean_k = str(k).lower().strip()
                    super().__setitem__(clean_k, v if isinstance(v, dict) else {"status": str(v)})

    def __contains__(self, item: Any) -> bool:
        if not item:
            return False
        clean_k = str(item).lower().strip()
        if super().__contains__(clean_k):
            return True
        if clean_k.startswith("http://") or clean_k.startswith("https://"):
            can_url = canonical_job_url(clean_k)
            if can_url and super().__contains__(can_url):
                return True
            job_id = extract_platform_job_id(clean_k)
            if job_id and super().__contains__(job_id):
                return True
        return False

    def __getitem__(self, item: Any) -> Any:
        return super().__getitem__(str(item).lower().strip())

    def __setitem__(self, key: Any, value: Any) -> None:
        clean_k = str(key).lower().strip()
        super().__setitem__(clean_k, value)

    def get(self, item: Any, default: Any = None) -> Any:
        return super().get(str(item).lower().strip(), default)

    def is_processed(self, url: str = None, company: str = None, title: str = None, platform: str = "") -> bool:
        """Convenience method to check URL, canonical URL, platform job ID, or composite key."""
        if url:
            clean_u = str(url).strip().lower()
            if clean_u in self:
                return True
            can = canonical_job_url(clean_u)
            if can in self:
                return True
            jid = extract_platform_job_id(clean_u, platform)
            if jid and jid in self:
                return True
        if company and title:
            clean_c = re.sub(r'[^a-z0-9]', '', str(company or '').lower())
            clean_t = re.sub(r'[^a-z0-9]', '', str(title or '').lower())
            if f"{clean_c}::{clean_t}" in self:
                return True
        return False

    def add(
        self,
        item: str,
        status: Optional[str] = None,
        metadata: Optional[Dict[str, Any]] = None,
        **kwargs
    ) -> None:
        if not item:
            return
        clean_key = str(item).lower().strip()
        meta = dict(metadata) if metadata else {}
        if kwargs:
            meta.update(kwargs)
        if status:
            meta["status"] = status
        meta.setdefault("timestamp", time.strftime("%Y-%m-%d %H:%M:%S"))

        if clean_key in self and isinstance(super().get(clean_key), dict):
            existing = dict(super().get(clean_key))
            existing.update({k: v for k, v in meta.items() if v is not None})
            super().__setitem__(clean_key, existing)
        else:
            super().__setitem__(clean_key, meta)

        # Index canonical URL and platform job ID if item is a URL
        if clean_key.startswith("http://") or clean_key.startswith("https://"):
            can_url = canonical_job_url(clean_key)
            if can_url and can_url != clean_key:
                super().__setitem__(can_url, meta)
            job_id = extract_platform_job_id(clean_key)
            if job_id:
                super().__setitem__(job_id, meta)

    def union(self, *others) -> "ProcessedLedger":
        res = ProcessedLedger(self)
        for other in others:
            if isinstance(other, dict):
                for k, v in other.items():
                    res.add(k, metadata=v if isinstance(v, dict) else {"status": str(v)})
            elif hasattr(other, "__iter__"):
                for item in other:
                    res.add(item)
        return res

    def intersection(self, other) -> set:
        other_keys = other.keys() if isinstance(other, dict) else other
        return set(self.keys()).intersection(other_keys)

    def difference(self, other) -> set:
        other_keys = other.keys() if isinstance(other, dict) else other
        return set(self.keys()).difference(other_keys)

    def __or__(self, other):
        return self.union(other)

    def __ior__(self, other):
        if isinstance(other, dict):
            for k, v in other.items():
                self.add(k, metadata=v if isinstance(v, dict) else {"status": str(v)})
        elif hasattr(other, "__iter__"):
            for item in other:
                self.add(item)
        return self

class CodebasePurityViolationError(RuntimeError):
    """Raised when hardcoded candidate values or profile paths are found in core engine scripts."""
    pass

class ProfileContext:
