def extract_ast_symbols(content: str) -> Dict[str, Any]:
    try:
        import ast as _ast
        tree = _ast.parse(content)
    except Exception:
        return {"functions": [], "classes": [], "imports": [], "calls": [], "summaries": []}
    functions, classes, imports, calls, summaries = [], [], [], [], []
    for node in _ast.walk(tree):
        if isinstance(node, _ast.FunctionDef):
            args = [a.arg for a in node.args.args][:6]
            doc = (_ast.get_docstring(node) or "").splitlines()
            first = doc[0].strip()[:140] if doc else ""
            functions.append({"name": node.name, "line": node.lineno, "args": args, "summary": first})
            summaries.append(f"def {node.name}({', '.join(args)}): {first}".strip())
        elif isinstance(node, _ast.ClassDef):
            doc = (_ast.get_docstring(node) or "").splitlines()
            first = doc[0].strip()[:140] if doc else ""
            classes.append({"name": node.name, "line": node.lineno, "summary": first})
            summaries.append(f"class {node.name}: {first}".strip())
        elif isinstance(node, _ast.Import):
            for a in node.names:
                imports.append(a.name.split(".")[0])
        elif isinstance(node, _ast.ImportFrom):
            if node.module:
                imports.append(node.module.split(".")[0])
        elif isinstance(node, _ast.Call):
            f = node.func
            if isinstance(f, _ast.Name):
                calls.append(f.id)
            elif isinstance(f, _ast.Attribute):
                calls.append(f.attr)
    return {"functions": functions, "classes": classes, "imports": imports, "calls": calls, "summaries": summaries[:12]}

def compute_pagerank(adjacency: Dict[str, List[Dict[str, str]]], damping: float = 0.85, iterations: int = 20) -> Dict[str, float]:
    nodes = list(adjacency.keys())
    for edges in adjacency.values():
        for e in edges:
            t = e.get("target")
            if t and t not in adjacency:
                nodes.append(t)
    nodes = sorted(set(nodes))
    n = len(nodes)
    if n == 0:
        return {}
    rank = {x: 1.0 / n for x in nodes}
    outdeg = {x: max(1, len(adjacency.get(x, []))) for x in nodes}
    incoming: Dict[str, List[str]] = {x: [] for x in nodes}
    for s, edges in adjacency.items():
        for e in edges:
            t = e.get("target")
            if t in incoming:
                incoming[t].append(s)
    for _ in range(iterations):
        new_rank = {}
        for x in nodes:
            s = sum(rank[src] / outdeg[src] for src in incoming[x])
            new_rank[x] = (1 - damping) / n + damping * s
        rank = new_rank
    return rank

class GraphMemoryEngine:
    """
    Semantic Graph Memory Query & Traversal Engine.
    """

    def __init__(self, graph_dir: Optional[Path] = None, current_workspace_uri: Optional[str] = None):
        self.graph_dir = Path(graph_dir) if graph_dir else GRAPH_DIR
        self.guard = WorkspaceGuard(current_workspace_uri=current_workspace_uri)
        self.nodes: Dict[str, Dict[str, Any]] = {}
        self.edges: List[Dict[str, Any]] = []
        self.adjacency: Dict[str, Any] = {}
        self.reload()

    def reload(self) -> None:
        nodes_file = self.graph_dir / "nodes.json"
        edges_file = self.graph_dir / "edges.json"
        index_file = self.graph_dir / "graph_index.json"

        if nodes_file.exists():
            with open(nodes_file, "r", encoding="utf-8") as f:
                data = json.load(f)
                self.nodes = {n["id"]: n for n in data.get("nodes", [])}

        if edges_file.exists():
            with open(edges_file, "r", encoding="utf-8") as f:
                data = json.load(f)
                self.edges = data.get("edges", [])

        if index_file.exists():
            with open(index_file, "r", encoding="utf-8") as f:
                data = json.load(f)
                self.adjacency = data.get("adjacency", {})

    def query_principles(self, tier: Optional[int] = 1) -> List[Dict[str, Any]]:
        """Retrieve cognitive principles filtered by tier."""
        results = []
        for n in self.nodes.values():
            if tier is None or n.get("tier") == tier:
                results.append(n)
        return results

    def get_related_nodes(self, node_id: str, relation_type: Optional[str] = None) -> List[Dict[str, Any]]:
        """Walks adjacent outgoing edges from node_id."""
        if node_id not in self.adjacency:
            return []
        connected = []
        raw_edges = self.adjacency[node_id]
        edges = raw_edges.get("outgoing", []) if isinstance(raw_edges, dict) else (raw_edges if isinstance(raw_edges, list) else [])
        for edge in edges:
            if not isinstance(edge, dict):
                continue
            if relation_type is None or edge.get("relation") == relation_type:
                target_node = self.nodes.get(edge.get("target"))
                if target_node:
                    connected.append({"node": target_node, "relation": edge.get("relation", "RELATED_TO")})
        return connected

    def get_workspace_memories(self, workspace_slug: str) -> List[Dict[str, Any]]:
        """Retrieves memories strictly scoped to a workspace after guard validation."""
        results = []
        for n in self.nodes.values():
            if n.get("tier") == 2:
                try:
                    if self.guard.filter_memory_access(n, target_workspace_id=workspace_slug):
                        results.append(n)
                except Exception:
                    pass
        return results

