    Loads all JSON knowledge cards representing the user's thinking patterns,
    instruction styles, session rules, debugging protocols, and goals.
    """

    def __init__(self, cards_dir: Optional[Path] = None):
        self.cards_dir = Path(cards_dir) if cards_dir else UNDERSTANDING_MASTER_DIR
        self.cards: Dict[str, Dict[str, Any]] = {}
        self.categories: Dict[str, List[Dict[str, Any]]] = {}
        self.reload()

    def reload(self) -> None:
        """Scans the understanding_master directory and reloads all JSON cards."""
        self.cards.clear()
        self.categories.clear()

        if not self.cards_dir.exists():
            return

        for json_file in self.cards_dir.rglob("*.json"):
            try:
                with open(json_file, "r", encoding="utf-8-sig") as f:
                    card_data = json.load(f)
                    card_id = card_data.get("id") or json_file.stem
                    cat = card_data.get("category") or json_file.parent.name
                    card_data["_file_path"] = str(json_file)
                    card_data["_category"] = cat

                    self.cards[card_id] = card_data
                    if cat not in self.categories:
                        self.categories[cat] = []
                    self.categories[cat].append(card_data)
            except Exception as e:
                print(f"[PersonaLoader] Warning: Failed to parse {json_file.name}: {e}")

    def get_card(self, card_id: str) -> Optional[Dict[str, Any]]:
        """Retrieve a specific card by its ID or stem."""
        return self.cards.get(card_id)

    def get_cards_by_category(self, category: str) -> List[Dict[str, Any]]:
        """Retrieve all cards belonging to a specific category."""
        return self.categories.get(category, [])

    def get_all_rules(self) -> List[Dict[str, Any]]:
        """Retrieve all session rules enforced by the user."""
        return self.get_cards_by_category("session_rules")

    def get_all_thinking_patterns(self) -> List[Dict[str, Any]]:
        """Retrieve all thinking patterns guiding the user."""
        return self.get_cards_by_category("thinking_patterns")

    def get_all_debugging_protocols(self) -> List[Dict[str, Any]]:
        """Retrieve all debugging protocols established by the user."""
        return self.get_cards_by_category("debugging_protocols")

    def get_master_summary(self) -> Dict[str, Any]:
        """Returns high-level statistics and meta-summary of loaded knowledge."""
        summary = {
            "total_cards": len(self.cards),
            "categories": {cat: len(cards) for cat, cards in self.categories.items()},
            "active_rules_count": len(self.get_all_rules()),
            "root_directory": str(self.cards_dir)
        }
        return summary

def run_cmd(cmd_list, cwd):
    result = subprocess.run(cmd_list, cwd=cwd, capture_output=True, text=True)
    if result.returncode != 0:
        log(f"Command failed: {' '.join(cmd_list)}\nError: {result.stderr}")
    return result.returncode == 0, result.stdout

class TranscriptLearner:
    """
    Parses conversation transcripts to extract behavioral insights about the user
    and updates or creates incremental knowledge cards.
    """

    def __init__(self, transcript_path: Optional[Path] = None, insights_dir: Optional[Path] = None):
        self.transcript_path = Path(transcript_path) if transcript_path else None
        self.insights_dir = Path(insights_dir) if insights_dir else LEARNED_INSIGHTS_DIR
        self.insights_dir.mkdir(parents=True, exist_ok=True)

    def extract_user_turns(self, path: Optional[Path] = None) -> List[Dict[str, Any]]:
        """Extracts all user input events from transcript.jsonl."""
        target_path = Path(path) if path else self.transcript_path
        if not target_path or not target_path.exists():
            return []

        user_turns = []
        with open(target_path, "r", encoding="utf-8", errors="ignore") as f:
            for line in f:
                try:
                    data = json.loads(line)
                    if data.get("type") == "USER_INPUT" or data.get("source") == "USER_EXPLICIT":
                        user_turns.append({
                            "step_index": data.get("step_index"),
                            "created_at": data.get("created_at"),
                            "content": data.get("content", "")
                        })
                except Exception:
                    pass
        return user_turns

    def analyze_patterns(self, user_turns: List[Dict[str, Any]]) -> Dict[str, Any]:
        """Analyzes user turns to extract behavioral and instructional trends."""
        tool_mentions: Dict[str, int] = {}
        constraints_detected: List[str] = []
        corrections_detected: List[str] = []
        rule_keywords = ["not allowed", "ensure not to", "developer mode", "rule", "restriction", "purity", "duplicate"]
        tool_regex = re.compile(r"/(browser|chrome-devtools|flutter-setup-declarative-routing|debug-optimize-lcp|troubleshooting|a11y-debugging|goal|grill-me)", re.IGNORECASE)

        for turn in user_turns:
            content = turn["content"]
            # Detect slash tools
            matches = tool_regex.findall(content)
            for m in matches:
                tool_key = f"/{m.lower()}"
                tool_mentions[tool_key] = tool_mentions.get(tool_key, 0) + 1

            # Detect constraints
            for kw in rule_keywords:
                if kw in content.lower():
                    snippet = content[:150].replace("\n", " ")
                    constraints_detected.append(f"[Step {turn['step_index']}] Keyword '{kw}': {snippet}...")

            # Detect corrective feedback
            if any(phrase in content.lower() for phrase in ["i saw you did not", "i saw that", "error", "failure", "fix"]):
                corrections_detected.append(f"[Step {turn['step_index']}] {content[:160].replace(chr(10), ' ')}...")

        analysis = {
            "total_user_prompts": len(user_turns),
            "tool_dispatch_frequency": tool_mentions,
            "sample_constraints": constraints_detected[:5],
            "sample_corrections": corrections_detected[:5],
            "analysis_timestamp": datetime.now().isoformat()
        }
        return analysis

    def persist_learning_session(self, session_id: str, analysis: Dict[str, Any]) -> Path:
        """Saves a structured learning session card into learned_insights/."""
        card_id = f"INSIGHT-{session_id}"
        card_path = self.insights_dir / f"session_{session_id}.json"

        card_data = {
            "id": card_id,
            "category": "learned_insights",
            "title": f"Learned Insights from Session {session_id}",
            "generated_at": datetime.now().isoformat(),
            "analysis": analysis
        }

        with open(card_path, "w", encoding="utf-8") as f:
            json.dump(card_data, f, indent=2, ensure_ascii=False)
            f.write("\n")
        return card_path

class CrossWorkspaceContaminationError(RuntimeError):
    """Raised when an agent attempts to apply a workspace-specific memory to an unrelated workspace."""
    pass

